#include <iostream>
#include <vector>
#include <string>
#include <deque>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    const int INF = 1000000000;
    vector<vector<pair<int, int>>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back({(int)e[1], 0});
        adj[e[1]].push_back({(int)e[0], 1});
    }
    vector<int> dist(n + 1, INF);
    dist[1] = 0;
    deque<int> dq;
    dq.push_back(1);
    while (!dq.empty()) {
        int u = dq.front();
        dq.pop_front();
        for (const auto& edge : adj[u]) {
            if (dist[u] + edge.second < dist[edge.first]) {
                dist[edge.first] = dist[u] + edge.second;
                if (edge.second == 0) dq.push_front(edge.first);
                else dq.push_back(edge.first);
            }
        }
    }
    cout << (dist[n] < INF ? dist[n] : -1) << "\n";

    return 0;
}

